from collections import deque

def can_reach_orthogonal(start_pos, avoid_color=None):
    """BFS to see if we can reach any 8 avoiding given obstacle color"""
    sr, sc = start_pos
    queue = deque([(sr, sc)])
    visited = {(sr, sc)}

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(demo_input) and 0 <= nc < len(demo_input[0]):
                if (nr, nc) not in visited:
                    val = demo_input[nr][nc]
                    # Can move through 6 (background), avoid specified color
                    if val != 8 or (avoid_color is not None and val == avoid_color):
                        visited.add((nr, nc))
                        if val == 8:
                            return True, (nr, nc)
                        queue.append((nr, nc))
    return False, None

