def can_reach_kings(start_pos, target_color=8, avoid_colors=None):
    """Can we move between start and any target_color cell using king's moves?"""
    sr, sc = start_pos

    # Build a graph of cells with target_color
    target_cells = set()
    for i in range(len(demo_input)):
        for j in range(len(demo_input[0])):
            if demo_input[i][j] == target_color:
                target_cells.add((i, j))

    # BFS with king's moves
    from collections import deque
    queue = deque([start_pos])
    visited = {start_pos}

    while queue:
        r, c = queue.popleft()
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(demo_input) and 0 <= nc < len(demo_input[0]):
                    if (nr, nc) not in visited:
                        val = demo_input[nr][nc]
