                        if val == 6 or val == start_pos[0] * 100 + start_pos[1] or ((avoid_colors is not None and val not in avoid_colors)):
                            visited.add((nr, nc))
                            if val == target_color:
                                return True, (nr, nc)
                            queue.append((nr, nc))
    return False, None

