# Find all isolated vertical bars (height >= 5, width 1, not adjacent to same color)
from collections import deque

def find_isolated_vertical_bars(grid):
    H, W = len(grid), len(grid[0])
    visited = [[False]*W for _ in range(H)]
    bars = []

    for c in range(W):
        # Scan down each column
        r = 0
        while r < H:
            if not visited[r][c] and grid[r][c] != 6:
                # Found start of a segment
                val = grid[r][c]
                seg_start = r
                seg_end = r

                # Count consecutive same value
                while r < H and grid[r][c] == val and not visited[r][c]:
                    visited[r][c] = True
                    seg_end += 1
                    r += 1

                seg_height = seg_end - seg_start

                if seg_height >= 5 and seg_height <= 10:
                    # Check if isolated (no same-color neighbors left/right)
                    isolated = True
                    for i in range(seg_start, seg_end):
                        # Check immediate left and right
                        for dc in [-1, 1]:
                            if 0 <= c + dc < W:
                                if grid[i][c+dc] == val:
                                    isolated = False
                                    break
                        if not isolated:
                            break

                    if isolated:
                        bars.append((val, seg_start, seg_end, c, seg_height))

    return bars

